use std::collections::HashMap;
use std::io::{self, Write};
use std::process::ExitCode;

/// Running total for one key. `None` means the total left the i64 range.
type Total = Option<i64>;

fn strip_cr(line: &[u8]) -> &[u8] {
    line.strip_suffix(b"\r").unwrap_or(line)
}

fn parse_value(bytes: &[u8]) -> Option<i64> {
    std::str::from_utf8(bytes).ok()?.trim().parse::<i64>().ok()
}

fn run(data: &[u8], out: &mut impl Write) -> io::Result<()> {
    let mut lines = data.split(|&b| b == b'\n').map(strip_cr);
    let mut totals: HashMap<&[u8], Total> = HashMap::new();

    // First section: records, up to the first empty line.
    for line in lines.by_ref() {
        if line.is_empty() {
            break;
        }
        let Some(pos) = line.iter().position(|&b| b == b' ') else {
            continue;
        };
        let (key, rest) = (&line[..pos], &line[pos + 1..]);
        let Some(value) = parse_value(rest) else {
            continue;
        };
        let entry = totals.entry(key).or_insert(Some(0));
        *entry = entry.and_then(|t| t.checked_add(value));
    }

    // Second section: queries.
    for key in lines {
        if key.is_empty() {
            continue;
        }
        out.write_all(key)?;
        match totals.get(key) {
            None => out.write_all(b"=absent\n")?,
            Some(None) => out.write_all(b"=overflow\n")?,
            Some(Some(t)) => writeln!(out, "={t}")?,
        }
    }
    out.flush()
}

fn main() -> ExitCode {
    let Some(path) = std::env::args_os().nth(1) else {
        eprintln!("usage: keyed_totals <file>");
        return ExitCode::from(2);
    };
    let data = match std::fs::read(&path) {
        Ok(d) => d,
        Err(e) => {
            eprintln!("cannot read {}: {e}", path.to_string_lossy());
            return ExitCode::from(1);
        }
    };
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    match run(&data, &mut out) {
        Ok(()) => ExitCode::SUCCESS,
        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => ExitCode::SUCCESS,
        Err(e) => {
            eprintln!("write error: {e}");
            ExitCode::from(1)
        }
    }
}
